#include <stdio.h>

int reverse_digits(int number) {
    int reversed = 0;
    while (number > 0) {
        reversed = reversed * 10 + number % 10;
        number /= 10;
    }
    return reversed;
}

int main() {
    printf("%d\n", reverse_digits(70815));
    return 0;
}
